statement:
One table records parking stays:

- `ParkingTransactions(lot_id, car_id, entry_time, exit_time, fee_paid)`: one row per stay of a car in a parking lot; `(lot_id, car_id, entry_time)` is unique. Every stay ends strictly after it starts, `fee_paid` is a non-negative amount with two decimals, and a car is never in two lots at the same time.

For every car, report:

- `car_id`;
- `total_fee_paid`: the sum of the fees of all its stays, in every lot;
- `avg_hourly_fee`: its total fee divided by its total parking time in hours (fractions of an hour count), rounded to 2 decimal places;
- `most_time_lot`: the lot where the car spent the most time, adding up all its stays in that lot. The data guarantees this lot is unique for every car.

Order the rows by `car_id` ascending.

validator:
function validate(input) {
  const [{ ParkingTransactions = [] }] = input;
  const keys = new Set(), stays = new Map(), stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const seconds = t => Date.parse(`${t.replace(' ', 'T')}Z`) / 1000;
  for (const [lot, car, entry, exit, fee] of ParkingTransactions) {
    if (lot === null || car === null) return 'Every stay needs a lot_id and a car_id.';
    if (!stamp.test(entry ?? '') || !stamp.test(exit ?? '')) return `Car ${car} needs times like 2023-06-01 08:00:00.`;
    const key = `${lot}/${car}/${entry}`;
    if (keys.has(key)) return `Car ${car} enters lot ${lot} at ${entry} twice.`;
    keys.add(key);
    if (!(entry < exit)) return `A stay of car ${car} must end after it starts.`;
    if (typeof fee !== 'number' || fee < 0 || Math.abs(fee * 100 - Math.round(fee * 100)) > 1e-6) return `Car ${car} needs a non-negative fee with at most two decimals.`;
    if (!stays.has(car)) stays.set(car, []);
    stays.get(car).push([seconds(entry), seconds(exit), lot]);
  }
  for (const [car, list] of stays) {
    list.sort((a, b) => a[0] - b[0]);
    for (let i = 1; i < list.length; i++) if (list[i][0] < list[i - 1][1]) return `Car ${car} cannot be in two lots at once.`;
    const time = new Map();
    for (const [entry, exit, lot] of list) time.set(lot, (time.get(lot) ?? 0) + exit - entry);
    const best = Math.max(...time.values());
    if ([...time.values()].filter(t => t === best).length > 1) return `Car ${car} has two lots tied for the most time.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const stamp = minutes => new Date(Date.UTC(2023, 5, 1, 7) + minutes * 60000).toISOString().slice(0, 19).replace('T', ' ');
  const cars = small ? [1001, 1002, 1003] : Array.from({ length: 200 }, (_, i) => 3001 + i);
  const lots = small ? [1, 2, 3] : Array.from({ length: 10 }, (_, i) => i + 1);
  const fees = [0, 1, 2, 2.5, 3, 4, 5, 6, 7.25, 10, 12.4];
  const gaps = [0, 0, 15, 30, 60, 120, 600, 1440];
  const count = small ? Math.floor(rand() * 6) : 1900;
  // Each car moves forward in time from its own clock, so its stays never overlap (gap 0 makes them touch).
  const clock = new Map(), rows = new Map();
  for (let i = 0; i < count; i++) {
    const car = small ? pick(cars) : cars[i % cars.length];
    const entry = (clock.get(car) ?? Math.floor(rand() * 8) * 30) + pick(gaps);
    const exit = entry + 15 * (1 + Math.floor(rand() * 16));
    clock.set(car, exit);
    if (!rows.has(car)) rows.set(car, []);
    rows.get(car).push([pick(lots), car, entry, exit, Math.round(pick(fees) * 100)]);
  }
  for (const [car, list] of rows) {
    // Break a tie for the longest lot with one more short stay in one of the tied lots.
    const time = new Map();
    for (const [lot, , entry, exit] of list) time.set(lot, (time.get(lot) ?? 0) + exit - entry);
    const best = Math.max(...time.values()), tied = [...time].filter(([, t]) => t === best).map(([lot]) => lot);
    if (tied.length > 1) {
      const entry = clock.get(car) + 30;
      list.push([tied[0], car, entry, entry + 15, 100]);
    }
    // Nudge the fee when the exact average would sit halfway between two cents.
    let cents = list.reduce((sum, row) => sum + row[4], 0);
    const minutes = list.reduce((sum, row) => sum + row[3] - row[2], 0);
    while ((cents * 120) % minutes === 0 && ((cents * 120) / minutes) % 2 === 1) { list[0][4] += 1; cents += 1; }
  }
  const ParkingTransactions = [];
  for (const list of rows.values()) for (const [lot, car, entry, exit, cents] of list) ParkingTransactions.push([lot, car, stamp(entry), stamp(exit), cents / 100]);
  for (let i = ParkingTransactions.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [ParkingTransactions[i], ParkingTransactions[j]] = [ParkingTransactions[j], ParkingTransactions[i]];
  }
  return [{ ParkingTransactions }];
}
